From c22d5ab9f6ae0782c2a472feb58f3b3acd5a03bc Mon Sep 17 00:00:00 2001
From: Dorota Czaplejewicz <dorota.czaplejewicz@puri.sm>
Date: Mon, 10 Sep 2018 08:32:23 +0000
Subject: [PATCH] imwayland: Fix clearing of preedit text

Fixes terminal emulator misbehaviour as outlined in https://gitlab.gnome.org/GNOME/gtk/issues/1316, which was introduced in 49b17e6c. The original commit cleared preedit text by setting it to an empty string, which still counted as existing preedit. The fix sets preedit string to null, which is correctly understood as not present.

diff --git a/modules/input/imwayland.c b/modules/input/imwayland.c
index 11d09d2007..1fe95f38a1 100644
--- a/modules/input/imwayland.c
+++ b/modules/input/imwayland.c
@@ -654,7 +654,7 @@ gtk_im_context_wayland_focus_out (GtkIMContext *context)
   commit_state (context_wayland);

   /* after disable, incoming state changes won't take effect anyway */
-  text_input_preedit (global, global->text_input, "", 0, 0);
+  text_input_preedit (global, global->text_input, NULL, 0, 0);
   text_input_preedit_apply (global);

   global->current = NULL;
-- 
2.25.1

        You will be given the root cause of a bug, the commit message and the corresponding patch.
        You need to extract all code statements that lead to the bug from the patch, based on the root cause and the commit message.

        Root cause:
        The bug was caused by the incorrect handling of the preedit text in the `gtk_im_context_wayland_focus_out` function, where setting the preedit text to an empty string (`""`) was still interpreted as existing preedit text, rather than indicating that there was no preedit text present. This led to misbehavior in terminal emulators that rely on the correct state of preedit text.

        Commit message:
        imwayland: Fix clearing of preedit text

Fixes terminal emulator misbehaviour as outlined in https://gitlab.gnome.org/GNOME/gtk/issues/1316, which was introduced in 49b17e6c. The original commit cleared preedit text by setting it to an empty string, which still counted as existing preedit. The fix sets preedit string to null, which is correctly understood as not present.  

        Patch:

 static void
 gtk_im_context_wayland_focus_out (GtkIMContext *context)
 {
   GtkIMContextWayland *context_wayland;

   if (global->current != context)
     return;

   context_wayland = GTK_IM_CONTEXT_WAYLAND (context);

   zwp_text_input_v3_disable (global->text_input);
   commit_state (context_wayland);

   /* after disable, incoming state changes won't take effect anyway */
-  text_input_preedit (global, global->text_input, "", 0, 0);
+  text_input_preedit (global, global->text_input, NULL, 0, 0);
   text_input_preedit_apply (global);

   global->current = NULL;
 }



